-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 9
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 9 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 09', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 09 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-09.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga a forma da entidade, do relacionamento e do atributo na notação de Chen.', 0.2, 'Entidade: **retângulo**; relacionamento: **losango**; atributo: **elipse** ligada à entidade.', 'Nota cheia (0,2): as três. Metade (0,1): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 1, 2, 'Explique como aparecem o identificador e a entidade fraca.', 0.4, 'Identificador: elipse com o **nome sublinhado** (ou bolinha preenchida no brModelo). Entidade fraca: **retângulo de linha dupla** (com relacionamento identificador em losango duplo).', 'Nota cheia (0,4): os dois. Metade (0,2): um. Zero (0): nenhum.'),
      (v_atividade, 1, 3, 'Explique como aparecem o atributo composto e a entidade associativa.', 0.4, 'Atributo composto: elipse **ligada a outras elipses** (as partes, ex.: endereço → rua, número). Associativa: **retângulo envolvendo o losango** do relacionamento.', 'Nota cheia (0,4): os dois. Metade (0,2): um. Zero (0): nenhum.'),
      (v_atividade, 2, 1, 'Liste as entidades e os relacionamentos com o verbo.', 0.2, 'Entidades: **LEITOR, EMPRÉSTIMO, LIVRO**. Relacionamentos: LEITOR —**faz**— EMPRÉSTIMO; EMPRÉSTIMO —**de**/refere-se a— LIVRO.', 'Nota cheia (0,2): entidades + relacionamentos com verbo. Metade (0,1): sem verbos. Zero (0): entidades erradas.'),
      (v_atividade, 2, 2, 'Escreva as cardinalidades (mín, máx) dos dois relacionamentos.', 0.4, '**LEITOR (1,1) — faz — (0,N) EMPRÉSTIMO**; **LIVRO (1,1) — (0,N) EMPRÉSTIMO** (um livro tem 0 ou vários empréstimos; cada empréstimo é de 1 livro).', 'Nota cheia (0,4): os dois relacionamentos corretos. Metade (0,2): um. Zero (0): nenhum.'),
      (v_atividade, 2, 3, 'Indique o identificador de cada entidade e dois atributos de EMPRÉSTIMO.', 0.4, '**id_leitor**, **id_livro**, **id_emprestimo**. Atributos de EMPRÉSTIMO: **data de retirada**, **data prevista de devolução**, **data de devolução** (também multa, situação).', 'Nota cheia (0,4): três identificadores + dois atributos. Metade (0,2): só uma das partes. Zero (0): nenhuma.'),
      (v_atividade, 3, 1, 'Diga o que significam o traço, o círculo e o tridente.', 0.2, 'Traço = **um**; círculo = **zero**; tridente = **muitos**.', 'Nota cheia (0,2): os três. Metade (0,1): dois. Zero (0): um ou nenhum.'),
      (v_atividade, 3, 2, 'Explique como cada entidade aparece nessa notação e o que deve estar indicado nela.', 0.4, 'Cada entidade é uma **caixa** com a **lista de atributos** (colunas), com a **chave primária (PK)** e as **chaves estrangeiras (FK)** indicadas.', 'Nota cheia (0,4): caixa + atributos + PK/FK. Metade (0,2): sem PK/FK. Zero (0): descreve losango.'),
      (v_atividade, 3, 3, 'Explique como um N:N aparece no modelo lógico em pé de galinha.', 0.4, 'O N:N aparece **resolvido por uma tabela associativa** no meio, ligada às duas entidades por relacionamentos **1:N** (tridente do lado da associativa).', 'Nota cheia (0,4): associativa + dois 1:N. Metade (0,2): só a associativa. Zero (0): linha direta N:N.'),
      (v_atividade, 4, 1, 'Descreva os símbolos das duas pontas da ligação CLIENTE–PEDIDO em pé de galinha.', 0.2, 'Do lado de **CLIENTE**: **dois traços** (exatamente um). Do lado de **PEDIDO**: **círculo e tridente** (zero ou muitos).', 'Nota cheia (0,2): os dois lados. Metade (0,1): um. Zero (0): invertidos.'),
      (v_atividade, 4, 2, 'Explique como fica PEDIDO–PRODUTO no modelo lógico, com a tabela do meio e suas colunas.', 0.4, 'Surge a tabela **ITEM_PEDIDO** entre PEDIDO e PRODUTO, com **id_pedido**, **id_produto**, **quantidade** e **preco_unitario**; PEDIDO 1:N ITEM_PEDIDO e PRODUTO 1:N ITEM_PEDIDO.', 'Nota cheia (0,4): tabela + colunas + ligações. Metade (0,2): tabela sem colunas. Zero (0): sem tabela do meio.'),
      (v_atividade, 4, 3, 'Indique as chaves primárias e estrangeiras das tabelas PEDIDO e da tabela do meio.', 0.4, 'PEDIDO: PK **id_pedido**; FK **id_cliente**. ITEM_PEDIDO: FKs **id_pedido** e **id_produto**; PK **composta (id_pedido, id_produto)** ou um id próprio.', 'Nota cheia (0,4): PK e FKs das duas tabelas. Metade (0,2): uma tabela correta. Zero (0): nenhuma.'),
      (v_atividade, 5, 1, 'Diga qual DER mostrar à diretora e qual mostrar ao desenvolvedor.', 0.2, 'Diretora: **DER conceitual** (Chen). Desenvolvedor: **DER lógico** (pé de galinha).', 'Nota cheia (0,2): os dois. Zero (0): invertidos.'),
      (v_atividade, 5, 2, 'Explique a diferença entre o DER conceitual e o DER lógico.', 0.4, 'O **conceitual** mostra o **negócio** (entidades, relacionamentos, cardinalidades) para **validar com o cliente**; o **lógico** mostra as **tabelas**, **colunas**, **chaves primárias e estrangeiras**, já com os N:N resolvidos.', 'Nota cheia (0,4): diferença com elementos dos dois. Metade (0,2): só um explicado. Zero (0): invertida.'),
      (v_atividade, 5, 3, 'Explique quais etapas seguintes o DER lógico prepara.', 0.4, 'A **normalização** (aula 10) e a escrita do **SQL de criação das tabelas** (DDL, aula 12).', 'Nota cheia (0,4): as duas. Metade (0,2): uma. Zero (0): nenhuma.'),
      (v_atividade, 6, 1, 'Diga qual é o primeiro passo do desenho.', 0.2, 'Colocar as **entidades fortes principais no centro** (ex.: ALUNO, PLANO, INSTRUTOR).', 'Nota cheia (0,2): passo correto. Zero (0): começar pelos atributos.'),
      (v_atividade, 6, 2, 'Escreva a ordem dos passos seguintes até os atributos.', 0.4, 'Ligar com os **relacionamentos e verbos** → marcar as **cardinalidades** nos dois lados → acrescentar **fracas e associativas** → acrescentar os **atributos**, sublinhando os identificadores.', 'Nota cheia (0,4): ordem completa. Metade (0,2): ordem com um passo faltando. Zero (0): ordem invertida.'),
      (v_atividade, 6, 3, 'Explique por que evitar linhas cruzadas e como padronizar os nomes.', 0.4, 'Linhas cruzadas deixam o diagrama **difícil de ler**, inclusive pelo cliente. Padronizar: nomes **no singular**, com o **mesmo estilo** (maiúsculas para entidades, minúsculas com sublinhado para atributos).', 'Nota cheia (0,4): motivo + padrão de nomes. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 7, 1, 'Indique uma ferramenta para cada necessidade.', 0.2, '(1) **brModelo**; (2) **draw.io**; (3) **pgAdmin ERD Tool**.', 'Nota cheia (0,2): as três. Metade (0,1): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 7, 2, 'Explique por que o brModelo é adequado ao ensino do modelo conceitual.', 0.4, 'O brModelo foi **feito para ensino**, desenha a **notação de Chen** (conceitual) e **gera o modelo lógico**, mostrando a passagem de um para o outro.', 'Nota cheia (0,4): ensino + Chen + geração do lógico. Metade (0,2): parcial. Zero (0): sem relação.'),
      (v_atividade, 7, 3, 'Explique a vantagem de gerar o SQL a partir do diagrama e o cuidado que ainda é preciso ter.', 0.4, 'Gerar o SQL **economiza tempo** e **mantém diagrama e banco iguais**. Cuidado: **conferir o SQL gerado** (tipos, restrições, nomes, chaves) antes de executar, pois a ferramenta não conhece todas as regras do negócio.', 'Nota cheia (0,4): vantagem + cuidado. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 8, 1, 'Liste os quatro problemas encontrados.', 0.2, '(1) PACIENTE **sem identificador**; (2) relacionamento **sem verbo**; (3) **telefone repetido** em duas entidades; (4) **requisito do convênio** ausente.', 'Nota cheia (0,2): os quatro. Metade (0,1): dois ou três. Zero (0): um ou nenhum.'),
      (v_atividade, 8, 2, 'Explique por que o telefone repetido em duas entidades é um problema.', 0.4, 'O mesmo dado em dois lugares é **redundância**: se o paciente muda o telefone, uma das cópias fica **desatualizada** (inconsistência).', 'Nota cheia (0,4): redundância + inconsistência. Metade (0,2): só um. Zero (0): diz que é correto.'),
      (v_atividade, 8, 3, 'Proponha a correção dos quatro problemas.', 0.4, '(1) acrescentar **id_paciente** (sublinhado); (2) nomear o relacionamento com verbo (ex.: **"agenda"/"realiza"**); (3) deixar o telefone **só em PACIENTE**; (4) acrescentar **convênio** (atributo de PACIENTE ou entidade CONVÊNIO ligada a ele).', 'Nota cheia (0,4): as quatro correções. Metade (0,2): duas ou três. Zero (0): uma ou nenhuma.'),
      (v_atividade, 9, 1, 'Escreva como você faria a sugestão ao autor, em forma de pergunta.', 0.2, 'Ex.: "**Uma turma pode ter mais de um professor?** Se sim, esse relacionamento não seria N:N?"', 'Nota cheia (0,2): sugestão em forma de pergunta, sem acusar. Metade (0,1): afirmação educada. Zero (0): acusação ("está errado").'),
      (v_atividade, 9, 2, 'Explique qual deve ser a atitude do autor diante da sugestão.', 0.4, '**Escutar** sem se defender, **verificar nos requisitos** (a turma pode ter mais de um professor?) e **aceitar** a mudança ou **justificar** por que manter.', 'Nota cheia (0,4): escutar + verificar + aceitar/justificar. Metade (0,2): dois dos três. Zero (0): recusar sem ouvir.'),
      (v_atividade, 9, 3, 'Explique por que registrar o que foi aceito e o que foi mantido, com o motivo.', 0.4, 'Para manter o **histórico das decisões**: o grupo e o professor sabem **o que mudou e por quê**, e evita-se voltar à mesma discussão depois.', 'Nota cheia (0,4): histórico + motivo. Metade (0,2): explicação vaga. Zero (0): sem relação.'),
      (v_atividade, 10, 1, 'Classifique as oito entidades em forte, fraca ou associativa.', 0.2, 'Fortes: **CURSO, TURMA, ALUNO, RESPONSÁVEL, PROFESSOR**. Associativas: **MATRÍCULA** (ALUNO–TURMA) e **AULA_TURMA** (PROFESSOR–TURMA). Fraca: **PARCELA**.', 'Nota cheia (0,2): todas corretas. Metade (0,1): um erro. Zero (0): dois ou mais.'),
      (v_atividade, 10, 2, 'Escreva os relacionamentos com cardinalidade (mín, máx) dos dois lados.', 0.4, 'CURSO (1,1)—oferece—(0,N) TURMA; ALUNO (1,1)—(0,N) MATRÍCULA (0,N)—(1,1) TURMA; MATRÍCULA (1,1)—gera—(1,N) PARCELA; RESPONSÁVEL (1,1)—responde por—(0,N) ALUNO; PROFESSOR (1,1)—(0,N) AULA_TURMA (0,N)—(1,1) TURMA.', 'Nota cheia (0,4): cinco relacionamentos coerentes. Metade (0,2): três ou quatro. Zero (0): dois ou menos.'),
      (v_atividade, 10, 3, 'Diga os atributos de MATRÍCULA e de PARCELA e o identificador de PARCELA.', 0.4, 'MATRÍCULA: **id_aluno, id_turma, data, situação, nota_final**. PARCELA: **número, vencimento, valor, data_pagamento** (e id_matricula). Identificador de PARCELA: **id_matricula + número**.', 'Nota cheia (0,4): atributos das duas + identificador. Metade (0,2): parcial. Zero (0): sem relação.');
end $$;
